link.script:
/* Convert consent bridge (Termly → Convert, "Option 1 / Step 2A"). */
( function () {
	var categories = ["analytics"];
	var state = window.rmConvertConsent = { granted: false, callbacks: [] };

	/* Run `cb` once consent has been given (immediately if it already was). */
	state.ready = function ( cb ) {
		if ( state.granted ) {
			cb();
		} else {
			state.callbacks.push( cb );
		}
	};

	/*
	 * Push revenue goals for a transaction — after consent, and at most once per
	 * transaction per tab (a thank-you page refresh must not count it again).
	 * Used by the thank-you page (rm_convert_revenue_script) and the one-click
	 * upsell AJAX handler in main.js.
	 */
	state.pushRevenue = function ( transactionId, goals ) {
		if ( ! transactionId || ! goals || ! goals.length ) {
			return;
		}
		var key = 'rm_conv_tx_' + transactionId;
		state.ready( function () {
			try {
				if ( window.sessionStorage.getItem( key ) ) {
					return;
				}
				window.sessionStorage.setItem( key, '1' );
			} catch ( e ) {}
			window._conv_q = window._conv_q || [];
			for ( var i = 0; i < goals.length; i++ ) {
				window._conv_q.push( goals[ i ] );
			}
		} );
	};

	function grant() {
		if ( state.granted ) {
			return;
		}
		state.granted = true;
		window._conv_q = window._conv_q || [];
		window._conv_q.push( { what: 'consentGiven' } ); // Syntax per Convert's consent docs (Option 1, Step 2A).
		while ( state.callbacks.length ) {
			try { state.callbacks.shift()(); } catch ( e ) {}
		}
	}

	function check( consent ) {
		if ( ! consent ) {
			return;
		}
		for ( var i = 0; i < categories.length; i++ ) {
			if ( true === consent[ categories[ i ] ] ) {
				grant();
				return;
			}
		}
	}

	function readStored() {
		try { check( window.Termly.getConsentState() ); } catch ( e ) {}
	}

	function bind() {
		var termly = window.Termly;
		if ( ! termly || 'function' !== typeof termly.on ) {
			return false;
		}
		termly.on( 'initialized', readStored );
		termly.on( 'consent', function ( data ) {
			check( data && data.consentState ? data.consentState : null );
			readStored();
		} );
		readStored();
		return true;
	}

	/*
	 * Convert only writes its `_conv_v` cookie after consent (Option 1), and uses it itself as
	 * the "consent already given" marker (see Convert's consent docs, Step 1). A returning
	 * visitor who has it has consented — don't wait for Termly, which WP Rocket delays until
	 * the first interaction.
	 */
	function hasConvertCookie() {
		try {
			if ( window.convert && 'function' === typeof window.convert.getCookie ) {
				return !! window.convert.getCookie( '_conv_v' );
			}
		} catch ( e ) {}
		return /(?:^|;\s*)_conv_v=/.test( document.cookie );
	}
	if ( hasConvertCookie() ) {
		grant();
	}

	/*
	 * Termly loads after this script, and WP Rocket "Delay JS" holds it back until the
	 * visitor's first interaction — so keep waiting for its API for the whole page view
	 * (checked every 250ms, gives up after 30 minutes).
	 */
	if ( ! bind() ) {
		var tries = 0;
		var timer = setInterval( function () {
			if ( bind() || ++tries > 7200 ) {
				clearInterval( timer );
			}
		}, 250 );
	}
}() );

